-- A plan may be paused and resumed. Each pause is kept: the day it was paused and the day it was
-- resumed (null while it is still paused). A plan date on or after the paused day and before the
-- resumed day is skipped: generating makes nothing for it and it is not among the next dates.
CREATE TABLE plan_pause (
    plan_id    BIGINT NOT NULL REFERENCES plan (id),
    paused_on  DATE NOT NULL,
    resumed_on DATE,
    CONSTRAINT plan_pause_dates CHECK (resumed_on IS NULL OR resumed_on >= paused_on)
);
package net.officefloor.hq.app.plan;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.ClaimController;
import net.officefloor.hq.app.claim.ClaimController.ClaimResponse;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing, adding, pausing and resuming the people's plans, and generating the claims they make. */
@RestController
@RequestMapping("/api/plans")
public class PlanController {

    public record ListPlansRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    /**
     * A plan's amount is one the claim form takes without a correction; every is a whole number of
     * days, or day a day of the month; exactly one of them is given.
     */
    public record AddPlanRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull Long personId, @NotNull @Pattern(regexp = ClaimController.AMOUNT) String amount,
            @NotNull LocalDate start, @Pattern(regexp = "\\d{1,6}") String every,
            @Pattern(regexp = "\\d{1,6}") String day, @NotNull LocalDate end) {
    }

    public record GenerateRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user) {
    }

    public record PlanActionRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull Long planId) {
    }

    public record PlanResponse(long id, long personId, String amount, LocalDate start, Integer every, Integer day,
            LocalDate end, int generated, String nextDates, boolean paused) {
    }

    /** What a generate did: how many claims were made, those claims in order, and the plans after it. */
    public record GenerateResponse(int made, List<ClaimResponse> claims, List<PlanResponse> plans) {
    }

    /** How many of a plan's next dates it shows. */
    private static final int NEXT_DATES = 5;

    private static PlanResponse response(Plan plan, LocalDate today) {
        return new PlanResponse(plan.getId(), plan.getPersonId(),
                plan.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), plan.getStart(),
                plan.getEvery(), plan.getDay(), plan.getEnd(), plan.getGenerated(),
                String.join(", ", plan.datesAfter(today, NEXT_DATES).stream().map(LocalDate::toString).toList()),
                plan.isPaused());
    }

    private static Integer number(String digits) {
        return digits == null || digits.isEmpty() ? null : Integer.valueOf(digits);
    }

    private final PlanService service;
    private final SheetService sheets;

    public PlanController(PlanService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    @PostMapping("/list")
    public List<PlanResponse> list(@Valid @RequestBody ListPlansRequest req) {
        String sheet = req.sheet().trim();
        LocalDate today = sheets.today(sheet);
        return service.list(sheet).stream().map(plan -> response(plan, today)).toList();
    }

    @PostMapping("/add")
    public PlanResponse add(@Valid @RequestBody AddPlanRequest req) {
        String sheet = req.sheet().trim();
        Plan plan = service.add(sheet, req.user().trim(), req.personId(), ClaimController.amount(req.amount()),
                req.start(), number(req.every()), number(req.day()), req.end());
        return response(plan, sheets.today(sheet));
    }

    @PostMapping("/pause")
    public PlanResponse pause(@Valid @RequestBody PlanActionRequest req) {
        String sheet = req.sheet().trim();
        Plan plan = service.pause(sheet, req.user().trim(), req.planId());
        return response(plan, sheets.today(sheet));
    }

    @PostMapping("/resume")
    public PlanResponse resume(@Valid @RequestBody PlanActionRequest req) {
        String sheet = req.sheet().trim();
        Plan plan = service.resume(sheet, req.user().trim(), req.planId());
        return response(plan, sheets.today(sheet));
    }

    @PostMapping("/generate")
    public GenerateResponse generate(@Valid @RequestBody GenerateRequest req) {
        String sheet = req.sheet().trim();
        List<ClaimResponse> made = service.generate(sheet, req.user().trim()).stream()
                .map(ClaimController::response).toList();
        LocalDate today = sheets.today(sheet);
        return new GenerateResponse(made.size(), made,
                service.list(sheet).stream().map(plan -> response(plan, today)).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * A person's plan: an amount, a start date, every so many days or a day of the month, and an end date.
 * Its plan dates are the start, then every that many days, up to the end; or, monthly, that day in
 * every month from the start's month (a day beyond the month's length on its last day), dates before
 * the start left out. It keeps each date it has made a claim for, and each time it was paused: a plan
 * date on or after a pause's day and before its resume's day is skipped, not postponed.
 */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    @Column(name = "every_days")
    private Integer every;

    @Column(name = "day_of_month")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_date", joinColumns = @JoinColumn(name = "plan_id"))
    @Column(name = "claim_date", nullable = false)
    private Set<LocalDate> made = new HashSet<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "plan_pause", joinColumns = @JoinColumn(name = "plan_id"))
    private List<PlanPause> pauses = new ArrayList<>();

    protected Plan() {
    }

    public Plan(String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
            Integer day, LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    /** Every how many days, or null for a monthly plan. */
    public Integer getEvery() {
        return every;
    }

    /** The day of the month of a monthly plan, or null. */
    public Integer getDay() {
        return day;
    }

    /** Whether the plan is paused now: its last pause has not been resumed. */
    public boolean isPaused() {
        return !pauses.isEmpty() && pauses.get(pauses.size() - 1).isOpen();
    }

    /** Pause the plan from the given day; false when it is already paused. */
    public boolean pause(LocalDate on) {
        if (isPaused()) {
            return false;
        }
        pauses.add(new PlanPause(on));
        return true;
    }

    /** Resume the plan on the given day; false when it is not paused. */
    public boolean resume(LocalDate on) {
        if (!isPaused()) {
            return false;
        }
        pauses.get(pauses.size() - 1).resume(on);
        return true;
    }

    /** Whether a plan date is skipped by a pause. */
    public boolean skips(LocalDate date) {
        return pauses.stream().anyMatch(p -> p.skips(date));
    }

    /** The plan's dates from its start up to and including the last, in order. */
    public List<LocalDate> datesUpTo(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
                dates.add(d);
            }
            return dates;
        }
        for (YearMonth month = YearMonth.from(start); !month.atDay(1).isAfter(last); month = month.plusMonths(1)) {
            LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!d.isBefore(start) && !d.isAfter(last)) {
                dates.add(d);
            }
        }
        return dates;
    }

    /**
     * The plan's first dates after the given day, up to and including its end, those a pause skips
     * left out: at most count, in order.
     */
    public List<LocalDate> datesAfter(LocalDate after, int count) {
        List<LocalDate> dates = new ArrayList<>();
        if (day == null) {
            LocalDate d = start;
            if (!start.isAfter(after)) {
                long steps = ChronoUnit.DAYS.between(start, after) / every + 1;
                d = start.plusDays(steps * every);
            }
            for (; dates.size() < count && !d.isAfter(end); d = d.plusDays(every)) {
                if (!skips(d)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        YearMonth month = YearMonth.from(after.isAfter(start) ? after : start);
        for (; dates.size() < count && !month.atDay(1).isAfter(end); month = month.plusMonths(1)) {
            LocalDate d = month.atDay(Math.min(day, month.lengthOfMonth()));
            if (!d.isBefore(start) && d.isAfter(after) && !d.isAfter(end) && !skips(d)) {
                dates.add(d);
            }
        }
        return dates;
    }

    public LocalDate getEnd() {
        return end;
    }

    /** Whether the plan has made its claim for this date. */
    public boolean hasMade(LocalDate date) {
        return made.contains(date);
    }

    public void markMade(LocalDate date) {
        made.add(date);
    }

    /** How many claims the plan has made so far. */
    public int getGenerated() {
        return made.size();
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A pause of a plan: the day it was paused, and the day it was resumed (null while still paused). */
@Embeddable
public class PlanPause {

    @Column(name = "paused_on", nullable = false)
    private LocalDate pausedOn;

    @Column(name = "resumed_on")
    private LocalDate resumedOn;

    protected PlanPause() {
    }

    PlanPause(LocalDate pausedOn) {
        this.pausedOn = pausedOn;
    }

    public LocalDate getPausedOn() {
        return pausedOn;
    }

    public LocalDate getResumedOn() {
        return resumedOn;
    }

    boolean isOpen() {
        return resumedOn == null;
    }

    void resume(LocalDate on) {
        resumedOn = on;
    }

    /** Whether a plan date falls in this pause: on or after the paused day and before the resumed day. */
    boolean skips(LocalDate date) {
        return !date.isBefore(pausedOn) && (resumedOn == null || date.isBefore(resumedOn));
    }
}
